(() => {
  'use strict';
  const units=()=>[...(window.RESEARCH_UNITS||[]),...(window.RESEARCH_UNIT_SUPPLEMENTS||[])];
  const enrich=id=>(window.PRECOMPUTED_ENRICHMENT||{})[id]||{};
  const activity=id=>(window.RESEARCH_ACTIVITY||{})[id]||{};
  const text=v=>String(v||'').replace(/\s+/g,' ').trim();
  const score=x=>{const e=enrich(x.id),a=activity(x.id);const papers=Array.isArray(e.recent_papers)&&e.recent_papers.length?e.recent_papers:(Array.isArray(a.papers)?a.papers:[]);const members=Array.isArray(e.current_members)?e.current_members.length:0;const pub=Array.isArray(e.verified_publication_pages)?e.verified_publication_pages.length:0;const recruit=Array.isArray(e.verified_recruitment_pages)?e.verified_recruitment_pages.length:0;const summary=text(e.research_summary);return(summary.length>=160?30:summary.length>=100?22:summary.length>=40?12:summary?5:0)+Math.min(Array.isArray(e.research_topics)?e.research_topics.length:0,10)*3+Math.min(Array.isArray(e.recommendation_keywords)?e.recommendation_keywords.length:0,12)*2+Math.min(papers.length,12)*4+Math.min(pub,5)*3+Math.min(members,20)*1.5+Math.min(recruit,4)*4+(e.member_page_url?5:0)+(String(e.poster_status||'').toLowerCase()==='verified'?15:0)+Math.min(Array.isArray(e.source_urls_used)?e.source_urls_used.length:0,15)*.5};
  const isEng=x=>/(공과대학|공학|college of engineering|engineering)/i.test(`${x.college||''} ${x.department||''}`);
  const isNat=x=>/(자연과학대학|자연대|college of natural sciences|natural science)/i.test(`${x.college||''} ${x.department||''}`);
  const pick=(arr,n)=>arr.filter(x=>text(x.name)).map(x=>({x,s:score(x)})).sort((a,b)=>b.s-a.s||text(a.x.name).localeCompare(text(b.x.name),'ko')).slice(0,n).map(v=>v.x);
  const groups=()=>{const all=units();const engNat=all.filter(x=>isEng(x)||isNat(x));const other=all.filter(x=>!isEng(x)&&!isNat(x));return{engNat:pick(engNat,2),other:pick(other,2)};};
  function openUnit(x){if(!x)return;const q=document.querySelector('#q'),old=q?q.value:'';if(q){q.value=String(x.name||'');q.dispatchEvent(new Event('input',{bubbles:true}));q.dispatchEvent(new Event('change',{bubbles:true}));}setTimeout(()=>{const lab=String(x.labs||x.title||'연구그룹').split(/[;|]/)[0].trim()||'연구그룹';const expected=`${String(x.name||'')} 교수 / ${lab}`;const card=[...document.querySelectorAll('#results .card')].find(c=>c.querySelector('h2')?.textContent.trim()===expected);if(card)card.click();else if(typeof window.openDetail==='function')window.openDetail(x);if(q){q.value=old;q.dispatchEvent(new Event('input',{bubbles:true}));}},80);}
  function panel(){if(document.querySelector('#showcaseChooser'))return;const b=document.querySelector('#showcaseOpen');if(!b)return;b.onclick=()=>{const sets=groups();const d=document.querySelector('#showcaseListDialog')||Object.assign(document.body.appendChild(document.createElement('dialog')),{id:'showcaseListDialog',className:'fav-dialog'});d.innerHTML='<button type="button" class="fav-close">×</button><h2>완성형 상세 예시</h2><p>현재 저장된 상세 데이터의 완성도가 가장 높은 연구실을 그룹별로 보여줍니다.</p>'+[['engNat','공과대학·자연과학대학 대표 2개'],['other','기타 단과대학 대표 2개']].map(([k,title])=>`<h3>${title}</h3><div class="showcase-items">${sets[k].map(x=>`<button type="button" data-id="${String(x.id).replace(/"/g,'&quot;')}">${text(x.name)} 교수 · ${text(x.labs||x.title||'연구그룹')}</button>`).join('')||'<span>현재 검증 데이터 없음</span>'}</div>`).join('');d.querySelector('.fav-close').onclick=()=>d.close();d.addEventListener('click',e=>{const btn=e.target.closest('[data-id]');if(btn){const x=units().find(u=>String(u.id)===String(btn.dataset.id));d.close();openUnit(x);}});if(!d.open)d.showModal();};const style=document.createElement('style');style.textContent='.showcase-items{display:flex;flex-direction:column;gap:8px;margin:8px 0 18px}.showcase-items button{padding:10px;text-align:left;border:1px solid #d7e2ee;border-radius:10px;background:#fff;cursor:pointer}.showcase-items button:hover{background:#f6f9fc}';document.head.appendChild(style);}
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',()=>setTimeout(panel,0));else setTimeout(panel,0);
})();
